INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS', 'PRET.G8.FOUNDA.DATA_SAFETY.DATA_PROTECT', 'skill', 'essential', 'Protecting data on a device (Pre-Technical Grade 8) keeps PINs and passwords safe. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE.M_AG8_SC_TERRACE', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE', 'Thinks terraces speed up water running down a slope.', '{"question":"What does terracing do on a slope?","wrong_answer":"Speeds up the water","correct_answer":"Slows the water and holds soil"}'::jsonb, 'The child sees the steps and pictures water falling down them faster.', 'Offer "Speeds up the water" next to the right answer and ask the question again in a new situation.', 'Pour water down a tray with and without small steps of soil; time it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE.M_AG8_SC_MULCH', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE', 'Thinks mulch leaves the soil bare.', '{"question":"What does mulch do to soil?","wrong_answer":"Leaves it bare","correct_answer":"Covers and protects it"}'::jsonb, 'The child confuses mulching with clearing the land.', 'Offer "Leaves it bare" next to the right answer and ask the question again in a new situation.', 'Lay mulch on a tray and show it covering the soil from raindrops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE.M_AG8_SC_CONTOUR', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE', 'Ploughs and plants up and down the slope.', '{"question":"How should crops be planted on a slope?","wrong_answer":"Up and down the slope","correct_answer":"Along the contour"}'::jsonb, 'Straight rows up the slope look neat and are easy to walk.', 'Offer "Up and down the slope" next to the right answer and ask the question again in a new situation.', 'Recall Grade 6: rows across the slope stop water; rows down the slope become channels.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE.M_AG8_SC_TRASH', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.SOIL_CONSERVE', 'Burns crop trash instead of laying it in trash lines.', '{"question":"What can be done with maize stalks after harvest to conserve soil?","wrong_answer":"Burn them to clear the field","correct_answer":"Lay them in lines across the slope as trash lines"}'::jsonb, 'Burning is the usual way to clear fields and the child does not see the trash as a tool.', 'Offer "Burn them to clear the field" next to the right answer and ask the question again in a new context.', 'Show a trash line holding soil behind it after rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY.M_AG8_CA_LEVEL', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY', 'Lays stone lines by eye, so they slope and water runs along them to one end.', '{"question":"How is a stone line laid on a slope?","wrong_answer":"By eye, roughly across","correct_answer":"Along a contour marked with an A-frame or line level"}'::jsonb, 'The child thinks "across" is close enough.', 'Offer "By eye, roughly across" next to the right answer and ask the question again in a new context.', 'Pour water along a tilted line on a model; it runs to the low end and cuts a gully.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY.M_AG8_CA_WATERWAY', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY', 'Thinks a grassed waterway should be left bare so water flows freely.', '{"question":"Why is a waterway planted with grass?","wrong_answer":"So it looks nice","correct_answer":"Grass holds the soil while the water flows over it"}'::jsonb, 'The child thinks water needs a clear channel.', 'Offer "So it looks nice" next to the right answer and ask the question again in a new context.', 'Run water down a bare channel and a grassed channel on a model.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY.M_AG8_CA_STRIPS', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY', 'Thinks strip cropping means planting strips running down the slope.', '{"question":"How are strips laid out in strip cropping?","wrong_answer":"Down the slope","correct_answer":"Across the slope, alternating crops with grass or cover crops"}'::jsonb, 'The child pictures strips as straight rows in any direction.', 'Offer "Down the slope" next to the right answer and ask the question again in a new context.', 'Draw both on a slope and trace where rain water goes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY.M_AG8_CA_REPAIR', 'AGRI.G8.CONSER.SOIL_CONSERVATION_MEASUR.CONSERVE_ACTIVITY', 'Thinks bunds and stone lines last for ever without repair.', '{"question":"What must be done to soil bunds after a heavy storm?","wrong_answer":"Nothing","correct_answer":"Check and repair breaks"}'::jsonb, 'The child thinks building is the end of the job.', 'Offer "Nothing" next to the right answer and ask the question again in a new context.', 'Show a broken bund with a gully below the break.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE.M_AG8_WS_COVER', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE', 'Leaves stored water uncovered.', '{"question":"How should stored water be kept?","wrong_answer":"Uncovered","correct_answer":"In a clean, covered container"}'::jsonb, 'The child thinks water is clean as long as it looks clear.', 'Offer "Uncovered" next to the right answer and ask the question again in a new situation.', 'Leave a basin of water uncovered for two days; look at the dust, insects and larvae.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE.M_AG8_WS_TREAT', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE', 'Drinks harvested rain water untreated because rain is pure.', '{"question":"What should be done before drinking harvested water?","wrong_answer":"Nothing","correct_answer":"Boil or purify it"}'::jsonb, 'The child knows rain falls clean and forgets the roof, gutters and tank.', 'Offer "Nothing" next to the right answer and ask the question again in a new situation.', 'Show the dirt washed off a roof in the first rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE.M_AG8_WS_MOSQUITO', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE', 'Thinks a tank is covered only to keep the water warm.', '{"question":"Why must water tanks be covered?","wrong_answer":"To warm the water","correct_answer":"To keep out dirt and mosquitoes"}'::jsonb, 'The child does not link open water with mosquitoes breeding.', 'Offer "To warm the water" next to the right answer and ask the question again in a new situation.', 'Show mosquito larvae in an open container; malaria mosquitoes breed in still water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE.M_AG8_WS_CHEMICAL', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.WATER_STORE', 'Stores drinking water in old chemical or fuel containers.', '{"question":"Which container is safe for storing drinking water?","wrong_answer":"An old paraffin jerrycan","correct_answer":"A clean container used only for water"}'::jsonb, 'The child thinks washing removes all traces.', 'Offer "An old paraffin jerrycan" next to the right answer and ask the question again in a new context.', 'Smell a washed paraffin can.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP.M_AG8_HS_FIRST', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP', 'Lets the first dirty rain from the roof go straight into the tank.', '{"question":"What is done with the first rain from a roof?","wrong_answer":"Let it into the tank","correct_answer":"Let it run away, then collect the cleaner water"}'::jsonb, 'The child does not want to waste any water.', 'Offer "Let it into the tank" next to the right answer and ask the question again in a new context.', 'Collect the first and the later rain in two glasses and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP.M_AG8_HS_GUTTER', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP', 'Fixes gutters flat or sloping away from the tank.', '{"question":"How must a gutter be fixed?","wrong_answer":"Flat along the roof","correct_answer":"Sloping gently towards the down pipe and tank"}'::jsonb, 'The child thinks water flows along any gutter.', 'Offer "Flat along the roof" next to the right answer and ask the question again in a new context.', 'Pour water into a flat gutter model: it stands and overflows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP.M_AG8_HS_TAP', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP', 'Fits the tank tap at the very bottom.', '{"question":"Why is the tank tap fitted a little above the bottom?","wrong_answer":"It should be at the very bottom","correct_answer":"So the dirt that settles at the bottom does not come out"}'::jsonb, 'The child wants to use every drop.', 'Offer "It should be at the very bottom" next to the right answer and ask the question again in a new context.', 'Let muddy water settle in a bottle; which layer would a bottom tap draw?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP.M_AG8_HS_CLEAN', 'AGRI.G8.CONSER.WATER_HARVESTING_AND_STO.HARVEST_SETUP', 'Never cleans the roof, gutters or tank.', '{"question":"How often should gutters and the tank be cleaned?","wrong_answer":"Never","correct_answer":"Before the rains and regularly after"}'::jsonb, 'The child thinks rain cleans the system.', 'Offer "Never" next to the right answer and ask the question again in a new context.', 'Show leaves and mud from a blocked gutter.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN.M_AG8_KG_SPACE', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN', 'Thinks a kitchen garden must be on a large farm far from the house.', '{"question":"Where is a kitchen garden kept?","wrong_answer":"On a distant large farm","correct_answer":"Near the house"}'::jsonb, 'The child links growing food with big fields.', 'Offer "On a distant large farm" next to the right answer and ask the question again in a new situation.', 'Show a keyhole garden two steps from a kitchen door.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN.M_AG8_KG_CROP', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN', 'Names timber trees or maize as crops for a kitchen garden.', '{"question":"Which crop suits a kitchen garden?","wrong_answer":"Timber trees","correct_answer":"Sukuma wiki"}'::jsonb, 'The child lists any plants grown at home.', 'Offer "Timber trees" next to the right answer and ask the question again in a new situation.', 'Ask what the cook needs every day: greens, onions, tomatoes, herbs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN.M_AG8_KG_MONEY', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN', 'Thinks a kitchen garden costs a family more than buying vegetables.', '{"question":"How does a kitchen garden help a family?","wrong_answer":"It costs a lot more","correct_answer":"It saves money on vegetables"}'::jsonb, 'The child pictures buying seeds and tools without counting what is saved.', 'Offer "It costs a lot more" next to the right answer and ask the question again in a new situation.', 'Count the shillings spent on sukuma wiki in a month against a packet of seed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN.M_AG8_KG_ONECROP', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.KITCHEN_GARDEN', 'Thinks a kitchen garden grows just one crop in a large amount.', '{"question":"What is grown in a kitchen garden?","wrong_answer":"One crop in a large amount","correct_answer":"A small mix of vegetables, herbs and spices"}'::jsonb, 'The child pictures a farm field of one crop.', 'Offer "One crop in a large amount" next to the right answer and ask the question again in a new context.', 'Show a kitchen garden plan with many small patches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP.M_AG8_GS_ALLONCE', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP', 'Plants all the vegetables on the same day, so they are ready together and then nothing.', '{"question":"How can a kitchen garden give vegetables all the time?","wrong_answer":"Plant everything on one day","correct_answer":"Plant small amounts every two or three weeks"}'::jsonb, 'The child does not plan ahead for a steady supply.', 'Offer "Plant everything on one day" next to the right answer and ask the question again in a new context.', 'Draw a harvest calendar for one planting and for staggered plantings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP.M_AG8_GS_FAR', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP', 'Sites the garden far from the house and water.', '{"question":"Where is a kitchen garden best placed?","wrong_answer":"Far from the house in the shade","correct_answer":"Near the house and water, in the sun"}'::jsonb, 'The child thinks gardens belong away from homes.', 'Offer "Far from the house in the shade" next to the right answer and ask the question again in a new context.', 'Ask how often the cook goes to pick greens, and how water is carried.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP.M_AG8_GS_FENCE', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP', 'Leaves the garden unfenced among chickens and goats.', '{"question":"Why fence a backyard garden?","wrong_answer":"It is not needed","correct_answer":"To keep chickens, goats and other animals out"}'::jsonb, 'The child thinks home animals will not eat the garden.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Show a bed scratched by chickens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP.M_AG8_GS_HERB', 'AGRI.G8.FOOD_P.KITCHEN_AND_BACKYARD_GAR.GARDEN_SETUP', 'Thinks herbs and spices cannot be grown at home.', '{"question":"Which herb can be grown in a kitchen garden?","wrong_answer":"None, herbs come only from shops","correct_answer":"Dhania, mint or rosemary"}'::jsonb, 'The child has seen herbs only in packets.', 'Offer "None, herbs come only from shops" next to the right answer and ask the question again in a new context.', 'Grow dhania in a tin in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD.M_AG8_PF_MOVE', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD', 'Thinks a fold stays in one place like a poultry house.', '{"question":"What is special about a fold?","wrong_answer":"It is never moved","correct_answer":"It is moved to fresh ground"}'::jsonb, 'The child pictures all poultry houses as fixed buildings.', 'Offer "It is never moved" next to the right answer and ask the question again in a new situation.', 'Show a fold with handles moved onto fresh grass; the old patch is manured.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD.M_AG8_PF_PROTECT', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD', 'Thinks a fold does not protect the birds from anything.', '{"question":"What does a fold protect birds from?","wrong_answer":"Nothing","correct_answer":"Predators and rain"}'::jsonb, 'The child sees the open mesh and thinks it is just a cage.', 'Offer "Nothing" next to the right answer and ask the question again in a new situation.', 'Ask what the roof and mesh keep out: hawks, dogs, mongooses, rain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD.M_AG8_PF_MANURE', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD', 'Thinks the droppings from a fold are wasted.', '{"question":"What happens to the manure from a fold?","wrong_answer":"It is wasted","correct_answer":"It is spread on the ground"}'::jsonb, 'The child links droppings with dirt to be swept away.', 'Offer "It is wasted" next to the right answer and ask the question again in a new situation.', 'Show the green patch where a fold stood last month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD.M_AG8_PF_BIG', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.POULTRY_FOLD', 'Thinks a fold is suitable for hundreds of birds.', '{"question":"Which flock suits a fold?","wrong_answer":"Hundreds of layers","correct_answer":"A small flock of a few birds"}'::jsonb, 'The child does not see that the fold must stay light enough to move.', 'Offer "Hundreds of layers" next to the right answer and ask the question again in a new context.', 'Ask two learners to lift a model fold built for many birds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD.M_AG8_FB_HEAVY', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD', 'Builds the fold from heavy timber and iron sheets so it is strong.', '{"question":"Why is a fold built from light materials?","wrong_answer":"Light materials are cheaper only","correct_answer":"So two people can move it to fresh ground"}'::jsonb, 'The child thinks strong means heavy.', 'Offer "Light materials are cheaper only" next to the right answer and ask the question again in a new context.', 'Try lifting a heavy model and a light one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD.M_AG8_FB_NOROOF', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD', 'Makes the fold all mesh with no roofed shelter.', '{"question":"Why does a fold need a roofed part?","wrong_answer":"It does not","correct_answer":"For shelter from rain and sun, and a place to lay and roost"}'::jsonb, 'The child thinks birds can live in the open like wild birds.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Ask where the birds go in a storm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD.M_AG8_FB_MESH', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD', 'Uses mesh with large holes or leaves gaps at the joints.', '{"question":"Why must the fold mesh have small holes and no gaps?","wrong_answer":"Big holes let in more air","correct_answer":"Predators such as mongooses and snakes get through gaps"}'::jsonb, 'The child thinks only of big predators like dogs.', 'Offer "Big holes let in more air" next to the right answer and ask the question again in a new context.', 'Show how a mongoose fits through a small gap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD.M_AG8_FB_SIZE', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_BUILD', 'Builds a tiny fold and crowds many birds into it.', '{"question":"How big should a fold be?","wrong_answer":"As small as possible","correct_answer":"Big enough for each bird to move, eat and rest without crowding"}'::jsonb, 'The child wants to save materials.', 'Offer "As small as possible" next to the right answer and ask the question again in a new context.', 'Draw ten birds in a tiny run; ask what happens at feeding time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING.M_AG8_FR_LITTER', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING', 'Sweeps up and throws away the droppings after moving the fold.', '{"question":"What happens to the droppings left where the fold stood?","wrong_answer":"They are swept away as rubbish","correct_answer":"They are left to manure the grass or garden"}'::jsonb, 'The child sees droppings only as dirt.', 'Offer "They are swept away as rubbish" next to the right answer and ask the question again in a new context.', 'Show the greener grass where the fold stood last week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING.M_AG8_FR_STAY', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING', 'Leaves the fold on the same patch for weeks.', '{"question":"How often is a fold moved?","wrong_answer":"Once a term","correct_answer":"Every few days, to fresh ground"}'::jsonb, 'The child thinks moving is a one-off.', 'Offer "Once a term" next to the right answer and ask the question again in a new context.', 'Look at a patch under a fold left for weeks: bare, muddy and smelly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING.M_AG8_FR_WATER', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING', 'Gives water only in the morning.', '{"question":"How often do poultry in a fold need water?","wrong_answer":"Once in the morning","correct_answer":"Clean water all day, refilled as needed"}'::jsonb, 'The child thinks birds drink once like a person at a meal.', 'Offer "Once in the morning" next to the right answer and ask the question again in a new context.', 'Check the waterer at midday on a hot day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING.M_AG8_FR_SUN', 'AGRI.G8.FOOD_P.POULTRY_REARING_IN_A_FOL.FOLD_REARING', 'Moves the fold into full sun at midday with no shade.', '{"question":"Where should a fold stand on a hot afternoon?","wrong_answer":"In full sun","correct_answer":"Where the roofed part gives shade, or under a tree"}'::jsonb, 'The child forgets birds suffer in heat.', 'Offer "In full sun" next to the right answer and ask the question again in a new context.', 'Show panting birds in strong sun.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE.M_AG8_PD_PEST', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE', 'Names a disease such as blight as a pest.', '{"question":"Which is a pest of vegetables?","wrong_answer":"Blight","correct_answer":"Aphids"}'::jsonb, 'Pests and diseases are taught together and both damage crops.', 'Offer "Blight" next to the right answer and ask the question again in a new situation.', 'A pest is an animal you can see eating the crop; a disease shows as spots, rot or wilting caused by germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE.M_AG8_PD_DISEASE', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE', 'Names a pest such as aphids as a disease.', '{"question":"Which is a disease of vegetables?","wrong_answer":"Aphids","correct_answer":"Blight"}'::jsonb, 'The child swaps the two words learnt together.', 'Offer "Aphids" next to the right answer and ask the question again in a new situation.', 'Look at aphids through a hand lens: they are tiny insects, so they are pests.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE.M_AG8_PD_CONTROL', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE', 'Names leaving weeds to grow as a way to control pests.', '{"question":"Which helps to control pests?","wrong_answer":"Leaving weeds to grow","correct_answer":"Crop rotation"}'::jsonb, 'The child thinks weeds distract pests from the crop.', 'Offer "Leaving weeds to grow" next to the right answer and ask the question again in a new situation.', 'Weeds hide pests and carry diseases; clear them and rotate crops.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE.M_AG8_PD_CUTWORM', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_DISEASE', 'Thinks seedlings cut off at the ground were broken by the wind.', '{"question":"Kale seedlings are found cut off at soil level in the morning. What caused it?","wrong_answer":"Strong wind","correct_answer":"Cutworms feeding at night"}'::jsonb, 'The child does not know pests that hide in the soil by day.', 'Offer "Strong wind" next to the right answer and ask the question again in a new context.', 'Dig gently round a cut seedling to find the curled grey cutworm.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS.M_AG8_PCM_COMPOST', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS', 'Puts diseased plants on the compost heap.', '{"question":"What is done with tomato plants killed by blight?","wrong_answer":"Put them on the compost heap","correct_answer":"Uproot them and burn or bury them away from the garden"}'::jsonb, 'The child knows plant waste goes on compost.', 'Offer "Put them on the compost heap" next to the right answer and ask the question again in a new context.', 'Recall Grade 4: diseased plants spread disease through compost.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS.M_AG8_PCM_SAME', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS', 'Plants tomatoes in the same bed season after season.', '{"question":"How does crop rotation help control disease?","wrong_answer":"It does not","correct_answer":"Diseases in the soil die out when their crop is not grown there"}'::jsonb, 'The child sees no link between the bed and the disease.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Show a bed where tomatoes failed three years running.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS.M_AG8_PCM_LATE', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS', 'Waits until most plants are damaged before acting.', '{"question":"When is the best time to control pests?","wrong_answer":"When most plants are damaged","correct_answer":"As soon as the first signs are seen"}'::jsonb, 'The child thinks a few pests do no harm.', 'Offer "When most plants are damaged" next to the right answer and ask the question again in a new context.', 'Show how a few aphids become thousands in two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS.M_AG8_PCM_SPRAY', 'AGRI.G8.FOOD_P.CROP_PEST_AND_DISEASE_CO.PEST_CONTROL_METHODS', 'Thinks learners can mix and spray farm chemicals themselves.', '{"question":"Who should spray chemical pesticides?","wrong_answer":"Any learner","correct_answer":"Only a trained adult with protective clothing"}'::jsonb, 'The child has seen chemicals sprayed and thinks it is simple.', 'Offer "Any learner" next to the right answer and ask the question again in a new context.', 'Read the warning symbols on a pesticide label.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS.M_AG8_FP_ORDER', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS', 'Dries or fries fish whole before scaling and gutting.', '{"question":"What is done first to fresh fish?","wrong_answer":"Drying it whole","correct_answer":"Scaling and gutting"}'::jsonb, 'The child has seen whole dried fish at the market and thinks they are not cleaned.', 'Offer "Drying it whole" next to the right answer and ask the question again in a new situation.', 'Gut and scale first: the gut spoils fastest; then clean, salt and dry or fry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS.M_AG8_FP_METHOD', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS', 'Thinks leaving fish uncovered in the sun preserves it.', '{"question":"Which makes fish last longer?","wrong_answer":"Leaving it in the sun uncovered","correct_answer":"Drying or smoking"}'::jsonb, 'The child knows sun drying and thinks any sun works.', 'Offer "Leaving it in the sun uncovered" next to the right answer and ask the question again in a new situation.', 'Compare fish dried salted on a raised rack under a net with fish left on the ground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS.M_AG8_FP_SAFE', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS', 'Thinks any learner may gut fish with a sharp knife alone.', '{"question":"Who uses the knife to gut fish at school?","wrong_answer":"Any learner alone","correct_answer":"The teacher"}'::jsonb, 'The child has used knives at home and does not think of the risk in class.', 'Offer "Any learner alone" next to the right answer and ask the question again in a new situation.', 'At school the teacher uses the knife; learners scale with a blunt scaler and gloves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS.M_AG8_PD_ORDER', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS', 'Plucks the bird before it is slaughtered and bled.', '{"question":"Which comes first in dressing a bird?","wrong_answer":"Plucking","correct_answer":"Slaughter and bleeding"}'::jsonb, 'The child pictures the feathers coming off first because they are on the outside.', 'Offer "Plucking" next to the right answer and ask the question again in a new situation.', 'Order: humane slaughter and bleeding by an adult, scald, pluck, remove offal, wash, chill.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS.M_AG8_PD_SCALD', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS', 'Thinks feathers are loosened by rubbing with soil or drying in the sun instead of scalding in hot water.', '{"question":"What is done to loosen feathers?","wrong_answer":"Rubbing with soil","correct_answer":"Scalding in hot water"}'::jsonb, 'The child has not seen a bird dressed and guesses a dry method.', 'Offer "Rubbing with soil" next to the right answer and ask the question again in a new situation.', 'Dip a feather in hot water (by the teacher) and show how it slides out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS.M_AG8_PD_SAFE', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS', 'Thinks learners may slaughter poultry alone.', '{"question":"Who slaughters poultry at school?","wrong_answer":"Any learner alone","correct_answer":"The teacher"}'::jsonb, 'The child has seen it done at home.', 'Offer "Any learner alone" next to the right answer and ask the question again in a new situation.', 'Slaughter is done humanely by a trained adult; learners help with plucking and cleaning.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS.M_AG8_FP_SALT', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.FISH_PROCESS', 'Thinks salting fish is only for taste.', '{"question":"Why is fish salted before drying?","wrong_answer":"Only for taste","correct_answer":"Salt draws out water and stops germs, so the fish keeps"}'::jsonb, 'The child links salt only with flavour.', 'Offer "Only for taste" next to the right answer and ask the question again in a new context.', 'Salt a slice of fish and watch water come out over an hour.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS.M_AG8_PD_OFFAL', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS', 'Leaves the gut inside the bird for a day before cleaning it.', '{"question":"When should the offal be removed from a dressed bird?","wrong_answer":"The next day","correct_answer":"Straight after plucking"}'::jsonb, 'The child does not know the gut spoils the meat quickly.', 'Offer "The next day" next to the right answer and ask the question again in a new context.', 'Smell a bird left uncleaned (from the teacher''s account).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS.M_AG8_PD_ROUGH', 'AGRI.G8.FOOD_P.PREPARATION_OF_ANIMAL_PR.POULTRY_DRESS', 'Thinks rough handling or chasing the bird before slaughter does not matter.', '{"question":"Why should a bird be handled calmly before slaughter?","wrong_answer":"It does not matter","correct_answer":"It is kinder, and calm birds give better meat"}'::jsonb, 'The child does not think about the animal''s suffering.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Talk about humane handling: calm, quick, by a trained adult.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE.M_AG8_MP_BOIL', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE', 'Thinks raw milk left in the sun lasts longest.', '{"question":"How can milk be kept longer?","wrong_answer":"By leaving it raw in the sun","correct_answer":"By boiling and cooling it"}'::jsonb, 'The child does not link warmth with germs growing.', 'Offer "By leaving it raw in the sun" next to the right answer and ask the question again in a new situation.', 'Boil and cool one cup and leave one raw in the sun; smell both in the evening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE.M_AG8_MP_FERMENT', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE', 'Thinks fermenting spoils milk.', '{"question":"Which preserves milk by fermenting?","wrong_answer":"Boiling dry","correct_answer":"Making yoghurt"}'::jsonb, 'The child links sour milk with bad milk.', 'Offer "Boiling dry" next to the right answer and ask the question again in a new situation.', 'Mala and yoghurt are milk soured by useful microbes on purpose; they keep longer.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE.M_AG8_MP_CONTAINER', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE', 'Stores milk in an unwashed container.', '{"question":"How should milk be stored?","wrong_answer":"In a dirty can","correct_answer":"In a clean, covered container"}'::jsonb, 'The child sees the old milk as harmless.', 'Offer "In a dirty can" next to the right answer and ask the question again in a new situation.', 'Old milk left in a can carries germs that spoil the new milk fast.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE.M_AG8_ME_DRY', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE', 'Thinks drying spoils meat.', '{"question":"Which method preserves meat?","wrong_answer":"Leaving it wet in the sun","correct_answer":"Drying it"}'::jsonb, 'The child sees dry meat as old meat.', 'Offer "Leaving it wet in the sun" next to the right answer and ask the question again in a new situation.', 'Show nyirinyiri or biltong: thin strips salted and dried keep for weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE.M_AG8_ME_COLD', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE', 'Keeps raw meat warm and uncovered.', '{"question":"How should raw meat be kept?","wrong_answer":"Warm and uncovered","correct_answer":"Cold and covered"}'::jsonb, 'The child does not link warmth and flies with spoiling.', 'Offer "Warm and uncovered" next to the right answer and ask the question again in a new situation.', 'Leave a piece of meat warm and uncovered and one cold and covered; compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE.M_AG8_ME_SALT', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE', 'Thinks salting makes meat spoil faster.', '{"question":"What does salting do to meat?","wrong_answer":"Spoils it faster","correct_answer":"Helps it last longer"}'::jsonb, 'The child thinks anything added to meat changes it for the worse.', 'Offer "Spoils it faster" next to the right answer and ask the question again in a new situation.', 'Salt draws out water so germs cannot grow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE.M_AG8_MP_COOLER', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MILK_PRESERVE', 'Thinks milk can be kept cool only in an electric fridge.', '{"question":"How can milk be kept cool at home without electricity?","wrong_answer":"It cannot","correct_answer":"In a clay pot in wet sand or a charcoal cooler"}'::jsonb, 'The child has seen cooling only in fridges.', 'Offer "It cannot" next to the right answer and ask the question again in a new context.', 'Feel the inside of a clay pot standing in wet sand.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE.M_AG8_ME_THICK', 'AGRI.G8.FOOD_P.PRESERVING_ANIMAL_PRODUC.MEAT_PRESERVE', 'Dries meat in thick pieces.', '{"question":"Why is meat cut into thin strips for drying?","wrong_answer":"It does not matter","correct_answer":"Thin strips dry quickly before germs spoil them"}'::jsonb, 'The child thinks drying works on any size.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Recall Grade 6: thin slices of fruit dried fast, thick ones rotted.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL.M_AG8_BM_ENERGY', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL', 'Calls beans an energy food rather than a body-building food.', '{"question":"Which is an energy food?","wrong_answer":"Beans","correct_answer":"Ugali"}'::jsonb, 'Beans fill the stomach, so the child thinks they mainly give energy.', 'Offer "Beans" next to the right answer and ask the question again in a new situation.', 'Recall Grade 5: beans are rich in protein, a body-building nutrient.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL.M_AG8_BM_PROTEIN', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL', 'Calls ugali a body-building food.', '{"question":"Which is a body-building food?","wrong_answer":"Ugali","correct_answer":"Beans"}'::jsonb, 'The child links a big filling plate with growing.', 'Offer "Ugali" next to the right answer and ask the question again in a new situation.', 'Ugali is mainly carbohydrate: it gives energy.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL.M_AG8_BM_PROTECT', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL', 'Calls sugar a protective food.', '{"question":"Which is a protective food?","wrong_answer":"Sugar","correct_answer":"Vegetables"}'::jsonb, 'The child links sweet with fruit, and fruit is protective.', 'Offer "Sugar" next to the right answer and ask the question again in a new situation.', 'Sugar gives energy only; fruits and vegetables protect the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL.M_AG8_BM_SAME', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.BALANCED_MEAL', 'Thinks every person in the family needs exactly the same meal and amount.', '{"question":"Does a toddler need the same plate as a farm worker?","wrong_answer":"Yes, everyone eats the same","correct_answer":"No, age, health and activity change what and how much each needs"}'::jsonb, 'The child sees the family pot shared out equally.', 'Offer "Yes, everyone eats the same" next to the right answer and ask the question again in a new context.', 'Compare the needs of a baby, a pregnant mother and a farm worker.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP.M_AG8_MPR_ORDER', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP', 'Cooks the quick foods first, so they are cold by the time the beans are ready.', '{"question":"In what order should a meal of beans, rice and cabbage be cooked?","wrong_answer":"Cabbage first, then rice, then beans","correct_answer":"Beans first (longest), then rice, then cabbage last"}'::jsonb, 'The child cooks in the order the foods are listed.', 'Offer "Cabbage first, then rice, then beans" next to the right answer and ask the question again in a new context.', 'Write each food''s cooking time and plan backwards from serving time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP.M_AG8_MPR_STYLE', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP', 'Mixes up family style and blue plate style serving.', '{"question":"What is blue plate service?","wrong_answer":"Dishes put on the table for everyone to help themselves","correct_answer":"Each person''s food is put on their plate in the kitchen"}'::jsonb, 'The two style names do not describe what happens.', 'Offer "Dishes put on the table for everyone to help themselves" next to the right answer and ask the question again in a new context.', 'Act out both services in class.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP.M_AG8_MPR_BUDGET', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP', 'Thinks a balanced meal must include meat, so it is too costly.', '{"question":"Can a balanced meal be made without meat?","wrong_answer":"No, meat is needed","correct_answer":"Yes, beans, ndengu, eggs or omena give protein cheaply"}'::jsonb, 'The child links protein only with meat.', 'Offer "No, meat is needed" next to the right answer and ask the question again in a new context.', 'Price a githeri and greens meal against a meat meal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP.M_AG8_MPR_SICK', 'AGRI.G8.FOOD_P.COOKING_PREPARING_A_BALA.MEAL_PREP', 'Plans the same heavy fried meal for a sick person.', '{"question":"What should a meal for someone recovering from illness be like?","wrong_answer":"Heavy and fried","correct_answer":"Light, soft, easy to digest and nourishing, with plenty of fluids"}'::jsonb, 'The child does not think about health status.', 'Offer "Heavy and fried" next to the right answer and ask the question again in a new context.', 'Ask what a sick person feels like eating and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN.M_AG8_KC_DAILY', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN', 'Thinks a kitchen needs a full clean only once in a long while.', '{"question":"How often are dishes washed?","wrong_answer":"Once a year","correct_answer":"Every day"}'::jsonb, 'The child sees cleaning as a big event, not a routine.', 'Offer "Once a year" next to the right answer and ask the question again in a new situation.', 'Sort jobs into daily, weekly and special; dishes and surfaces are daily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN.M_AG8_KC_RAW', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN', 'Keeps raw meat with vegetables and cooked food on the same board.', '{"question":"How should raw meat be kept from vegetables?","wrong_answer":"Mixed together","correct_answer":"Kept apart"}'::jsonb, 'The child does not know germs pass from raw meat to food eaten raw.', 'Offer "Mixed together" next to the right answer and ask the question again in a new situation.', 'Use separate boards or wash between; raw meat juices carry germs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN.M_AG8_KC_WASTE', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN', 'Leaves kitchen waste under the table.', '{"question":"What should be done with kitchen waste?","wrong_answer":"Left under the table","correct_answer":"Disposed of properly"}'::jsonb, 'The child plans to take it out later and forgets the flies.', 'Offer "Left under the table" next to the right answer and ask the question again in a new situation.', 'Put waste in a covered bin and empty it daily.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN.M_AG8_KC_CLOTH', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_CLEAN', 'Uses one dirty cloth for dishes, tables and the floor.', '{"question":"Why use separate cloths for dishes and for the floor?","wrong_answer":"One cloth is enough","correct_answer":"Germs from the floor spread to dishes"}'::jsonb, 'The child thinks a cloth is a cloth.', 'Offer "One cloth is enough" next to the right answer and ask the question again in a new context.', 'Ask where the floor cloth has been.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE.M_AG8_KR_BOTTOM', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE', 'Mops the floor before wiping the shelves and stove.', '{"question":"Which is cleaned last in a kitchen?","wrong_answer":"The shelves","correct_answer":"The floor"}'::jsonb, 'The child starts with the biggest job.', 'Offer "The shelves" next to the right answer and ask the question again in a new context.', 'Wipe crumbs off a shelf onto a just-mopped floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE.M_AG8_KR_MIX', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE', 'Mixes bleach with other cleaners to make them stronger.', '{"question":"Why must cleaning agents not be mixed?","wrong_answer":"Mixing makes them stronger and better","correct_answer":"Some mixtures give off poisonous gases"}'::jsonb, 'The child thinks two cleaners are better than one.', 'Offer "Mixing makes them stronger and better" next to the right answer and ask the question again in a new context.', 'Read the warning on a bleach bottle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE.M_AG8_KR_STORE', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE', 'Never empties the food store, only adds to it.', '{"question":"What is special cleaning of a food store?","wrong_answer":"Adding new food","correct_answer":"Emptying it, scrubbing shelves, checking for pests and throwing out spoilt food"}'::jsonb, 'The child does not see the store as needing cleaning.', 'Offer "Adding new food" next to the right answer and ask the question again in a new context.', 'Show weevils and mouse droppings at the back of a store.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE.M_AG8_KR_SPONGE', 'AGRI.G8.HYGIEN.CLEANING_THE_KITCHEN.KITCHEN_ROUTINE', 'Leaves the dish sponge wet in the sink overnight.', '{"question":"What is done with dish cloths and sponges after washing up?","wrong_answer":"Leave them wet in the sink","correct_answer":"Wash, rinse and dry them in the air or sun"}'::jsonb, 'The child does not think germs grow in cloths.', 'Offer "Leave them wet in the sink" next to the right answer and ask the question again in a new context.', 'Smell a sponge left wet for two days.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS.M_AG8_SM_PLAIN', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS', 'Thinks a plain seam is made by gluing two edges together.', '{"question":"What is a plain seam?","wrong_answer":"Two edges glued","correct_answer":"Two pieces joined with a row of stitches"}'::jsonb, 'The child has seen glued crafts and has not sewn a seam.', 'Offer "Two edges glued" next to the right answer and ask the question again in a new situation.', 'Sew two pieces right sides together in a line of stitches: that is a plain seam.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS.M_AG8_SM_FRENCH', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS', 'Thinks a French seam leaves the raw edges showing.', '{"question":"What does a French seam do?","wrong_answer":"Leaves raw edges showing","correct_answer":"Encloses the raw edges"}'::jsonb, 'The child mixes up the seams by name.', 'Offer "Leaves raw edges showing" next to the right answer and ask the question again in a new situation.', 'Show a French seam: the raw edges are hidden inside a second line of stitching.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS.M_AG8_SM_USE', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS', 'Thinks seams are used in building walls, not in cloth items.', '{"question":"Where are seams used?","wrong_answer":"Only in walls","correct_answer":"In pillow cases and curtains"}'::jsonb, 'The child takes "seam" from other meanings of joining.', 'Offer "Only in walls" next to the right answer and ask the question again in a new situation.', 'Turn a pillow case inside out and find its seams.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS.M_AG8_SM_OPEN', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAMS', 'Thinks an open seam is one left unstitched.', '{"question":"What is an open seam?","wrong_answer":"A seam that is not sewn","correct_answer":"A seam whose turnings are pressed open flat on each side"}'::jsonb, 'The child takes "open" as "not closed".', 'Offer "A seam that is not sewn" next to the right answer and ask the question again in a new context.', 'Show an open seam pressed flat from the wrong side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING.M_AG8_SEW_RIGHT', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING', 'Places the wrong sides together when sewing a plain seam.', '{"question":"Which sides of the cloth face each other when sewing a plain seam?","wrong_answer":"The wrong sides","correct_answer":"The right sides"}'::jsonb, 'The child puts the nice sides out so they can be seen.', 'Offer "The wrong sides" next to the right answer and ask the question again in a new context.', 'Sew a sample wrong sides together and turn it: the raw edges show outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING.M_AG8_SEW_EDGE', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING', 'Stitches right at the raw edge.', '{"question":"How far from the edge is a seam stitched?","wrong_answer":"Right at the edge","correct_answer":"About 1.5 cm in, on the fitting line"}'::jsonb, 'The child wants to waste no cloth.', 'Offer "Right at the edge" next to the right answer and ask the question again in a new context.', 'Pull a seam stitched at the edge: the threads fray out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING.M_AG8_SEW_NEATEN', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING', 'Leaves the raw edges un-neatened.', '{"question":"Why are the raw edges of a seam neatened?","wrong_answer":"It is not needed","correct_answer":"To stop them fraying when the item is used and washed"}'::jsonb, 'The child thinks the inside does not matter.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Wash an un-neatened sample several times.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING.M_AG8_SEW_PRESS', 'AGRI.G8.PRODUC.SEWING_SKILLS_CONSTRUCTI.SEAM_MAKING', 'Never presses the seam.', '{"question":"Why is a seam pressed after sewing?","wrong_answer":"Only to look nice","correct_answer":"So it lies flat and the item takes a neat shape"}'::jsonb, 'The child sees pressing as decoration.', 'Offer "Only to look nice" next to the right answer and ask the question again in a new context.', 'Compare a pressed and an unpressed seam on a cushion.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS.M_AG8_WA_OPEN', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS', 'Thinks open troughs stay clean.', '{"question":"What is a problem of open troughs?","wrong_answer":"They stay perfectly clean","correct_answer":"They get dirty and spill"}'::jsonb, 'The child sees clean water poured in and not the dirt that falls in later.', 'Offer "They stay perfectly clean" next to the right answer and ask the question again in a new situation.', 'Look at an open trough at the end of the day: droppings, feathers, mud.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS.M_AG8_WA_SAVE', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS', 'Thinks an innovative waterer wastes water.', '{"question":"How does an innovative waterer help?","wrong_answer":"It wastes water","correct_answer":"It saves water"}'::jsonb, 'The child thinks anything new uses more.', 'Offer "It wastes water" next to the right answer and ask the question again in a new situation.', 'Measure water spilled from an open dish and from a bottle waterer in a day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS.M_AG8_WA_MATERIAL', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS', 'Names a heavy stone as material for a waterer.', '{"question":"Which can make a simple waterer?","wrong_answer":"A heavy stone","correct_answer":"A clean plastic bottle"}'::jsonb, 'The child thinks any container-shaped object will do.', 'Offer "A heavy stone" next to the right answer and ask the question again in a new situation.', 'Choose light, clean, cleanable reused containers such as plastic bottles and basins.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS.M_AG8_WA_HEIGHT', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERERS', 'Thinks a waterer works at any height for any animal.', '{"question":"Why is a chicken waterer raised to about the birds'' back height?","wrong_answer":"It does not matter","correct_answer":"So the birds can drink but cannot scratch litter into it or step in"}'::jsonb, 'The child does not watch how animals use a waterer.', 'Offer "It does not matter" next to the right answer and ask the question again in a new context.', 'Watch chickens at a waterer on the ground: they scratch dirt in.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN.M_AG8_WD_TEST', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN', 'Gives the waterer to the animals without testing it.', '{"question":"What is done after building a waterer?","wrong_answer":"Give it to the animals and leave it","correct_answer":"Test it for leaks and spills, watch the animals use it, then adjust"}'::jsonb, 'The child thinks building ends the job.', 'Offer "Give it to the animals and leave it" next to the right answer and ask the question again in a new context.', 'Test a bottle waterer that leaks onto the floor.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN.M_AG8_WD_CHEM', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN', 'Uses an old pesticide container for the waterer.', '{"question":"Can an old pesticide container be used as a waterer?","wrong_answer":"Yes, after washing","correct_answer":"No, poison stays in it"}'::jsonb, 'The child wants to reuse what is at hand.', 'Offer "Yes, after washing" next to the right answer and ask the question again in a new context.', 'Recall Grade 7: chemical containers are never reused for food or water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN.M_AG8_WD_CLEAN', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN', 'Designs a waterer that cannot be opened or cleaned.', '{"question":"Why must a waterer be easy to clean?","wrong_answer":"It does not need cleaning","correct_answer":"Slime and germs build up inside and must be washed out daily"}'::jsonb, 'The child thinks closed means clean.', 'Offer "It does not need cleaning" next to the right answer and ask the question again in a new context.', 'Look inside a sealed waterer after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN.M_AG8_WD_PROBLEM', 'AGRI.G8.PRODUC.CONSTRUCTING_INNOVATIVE_.WATERER_DESIGN', 'Starts building before naming the problem with the old waterer.', '{"question":"What is the first step in designing an innovative waterer?","wrong_answer":"Start building","correct_answer":"Name the problem with the existing waterer"}'::jsonb, 'The child is keen to make something.', 'Offer "Start building" next to the right answer and ask the question again in a new context.', 'List the problems found on the household visits.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES.M_AG8_IS_SERVICE', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES', 'Names a service that does not use ICT, such as a bus ride, as an ICT service.', '{"question":"Which service is reached through ICT?","wrong_answer":"A bus ride","correct_answer":"eCitizen"}'::jsonb, 'The child thinks any service people pay for is an ICT service.', 'Offer "A bus ride" next to the right answer and ask the question again in a new situation.', 'An ICT service is reached through a phone, computer or the internet: eCitizen, M-Pesa, weather SMS.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES.M_AG8_IS_WEATHER', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES', 'Thinks a weather forecast by SMS is of no use to a farmer.', '{"question":"How can a weather SMS help a farmer?","wrong_answer":"It cannot help","correct_answer":"It tells when rain is likely"}'::jsonb, 'The child thinks weather cannot be known in advance.', 'Offer "It cannot help" next to the right answer and ask the question again in a new situation.', 'Ask when a farmer should plant, spray or harvest; a forecast helps choose the day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES.M_AG8_IS_SAFE', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES', 'Shares a PIN or password with friends or callers.', '{"question":"What should you do with your password?","wrong_answer":"Share it","correct_answer":"Keep it private"}'::jsonb, 'The child trusts friends and people who sound official.', 'Offer "Share it" next to the right answer and ask the question again in a new situation.', 'Real services never ask for your PIN. Keep it private; tell an adult about such calls.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES.M_AG8_IS_VET', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_SERVICES', 'Thinks a farmer can get vet or extension advice only by travelling to an office.', '{"question":"How can a farmer get advice about a sick cow without travelling?","wrong_answer":"There is no way","correct_answer":"Through a phone helpline, SMS or app service for farmers"}'::jsonb, 'The child has not seen advice given by phone.', 'Offer "There is no way" next to the right answer and ask the question again in a new context.', 'Show a farmer helpline or SMS service with the teacher.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS.M_AG8_IA_FAKE', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS', 'Trusts any message or website that claims to be a service.', '{"question":"An SMS says you have won a prize and asks you to send money to claim it. What is it?","wrong_answer":"A real service; send the money","correct_answer":"A scam; do not reply and tell an adult"}'::jsonb, 'The child trusts official-sounding messages.', 'Offer "A real service; send the money" next to the right answer and ask the question again in a new context.', 'Compare a real service message with a scam message.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS.M_AG8_IA_CHECK', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS', 'Acts on market price information from one source without checking.', '{"question":"Why check market price information with another source?","wrong_answer":"It is not needed","correct_answer":"Prices change and one source can be wrong or old"}'::jsonb, 'The child thinks anything on a phone is true.', 'Offer "It is not needed" next to the right answer and ask the question again in a new context.', 'Compare prices from two services for the same day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS.M_AG8_IA_LOGOUT', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS', 'Leaves an account open on a shared computer.', '{"question":"What should you do after using an online service on a shared computer?","wrong_answer":"Just close the window","correct_answer":"Log out"}'::jsonb, 'The child thinks closing the window ends the session.', 'Offer "Just close the window" next to the right answer and ask the question again in a new context.', 'Show how the next user can open the account after the window is closed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS.M_AG8_IA_STEPS', 'AGRI.G8.PRODUC.ICT_SUPPORT_SERVICES.ICT_ACCESS', 'Dials random codes hoping to reach a service.', '{"question":"How do you find the right USSD code or number for a service?","wrong_answer":"Try any code","correct_answer":"Use the official code from the provider or a trusted source"}'::jsonb, 'The child guesses instead of looking up.', 'Offer "Try any code" next to the right answer and ask the question again in a new context.', 'Show where official codes are printed: posters, the provider''s website.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
